<script setup lang="ts">
// pattern: Imperative Shell
import { computed } from 'vue'
import { useI18n } from 'vue-i18n'
import type { WorkflowGraphNode } from '@/types/workflow'
import type { WorkflowRun } from '@/types/run'
const props = defineProps<{ nodes: WorkflowGraphNode[]; run: WorkflowRun | null; busy: boolean }>()
const emit = defineEmits<{ locate: [nodeId: string, field: string]; run: []; results: []; close: [] }>()
const { t } = useI18n({ useScope: 'local', messages: {
  'zh-CN': { title: '第一次运行向导', example: '模板提供示例配置，请替换输入并核实环境；成品以真实运行记录为准。', audio: '音频 → 转录 → 总结', image: '提示词 → 图像成品', input: '1. 准备输入', audioInput: '选择你上传的音频/视频文件；不要把模板占位内容当真实输入。', imageInput: '填写自己的提示词，需要图生图时选择源图片。', configure: '2. 检查配置', audioConfig: '打开 Whisper 环境助手核实模型和运行环境，再选择总结模型与输出格式。', imageConfig: '在图像连接助手选择已有连接，检查真实模型、参数及可执行能力。', run: '3. 运行', runHint: '运行前查看检查清单；仍需服务端校验。处理中请勿重复启动。', results: '4. 查看成品', resultsHint: '运行详情可展开、复制文本与 JSON；文件成品在文件页查看。', pending: '尚无当前工作流的真实运行结果', succeeded: '后端已确认运行成功，可查看输出', unconfirmed: '当前运行尚未确认成功，请查看状态和日志', open: '打开配置', start: '开始运行', view: '查看运行结果', files: '打开文件页', close: '收起向导', configureState: '配置步骤不代表环境已验证' },
  'en-US': { title: 'First-run guide', example: 'Templates provide sample configuration. Replace inputs and verify the environment; actual results come from run records.', audio: 'Audio → transcript → summary', image: 'Prompt → image', input: '1. Prepare input', audioInput: 'Select your uploaded audio/video file. Replace sample inputs.', imageInput: 'Enter your prompt and select a source image for image-to-image.', configure: '2. Check configuration', audioConfig: 'Use the Whisper environment assistant, then choose a summary model and export format.', imageConfig: 'Use the image connection assistant to check the connection, real models and parameters.', run: '3. Run', runHint: 'Review the checklist; server validation still applies. Do not start duplicates while processing.', results: '4. Use results', resultsHint: 'Expand and copy text or JSON in run details. File artifacts are on the files page.', pending: 'No real run result for this workflow yet', succeeded: 'The server confirmed success. Inspect the outputs.', unconfirmed: 'Success is not yet confirmed. Check status and logs.', open: 'Open configuration', start: 'Start run', view: 'View run results', files: 'Open files', close: 'Hide guide', configureState: 'Configuration is not environment verification' },
  'ja-JP': { title: '初回実行ガイド', example: 'テンプレートは設定例で、実際の結果ではありません。入力と環境を確認してください。', audio: '音声 → 文字起こし → 要約', image: 'プロンプト → 画像', input: '1. 入力を準備', audioInput: 'アップロードした音声・動画を選択してください。', imageInput: 'プロンプトと必要な入力画像を設定してください。', configure: '2. 設定を確認', audioConfig: 'Whisper 環境と要約モデル、出力形式を確認してください。', imageConfig: '画像接続アシスタントで接続、モデル、パラメーターを確認してください。', run: '3. 実行', runHint: 'チェックリストを確認してください。サーバー検証は引き続き必要です。重複実行を避けてください。', results: '4. 結果を使う', resultsHint: '詳細でテキストや JSON を展開・コピーできます。ファイルはファイルページにあります。', pending: 'このワークフローの実行結果はまだありません', succeeded: 'サーバーで成功が確認されました', unconfirmed: '成功は未確認です。状態とログを確認してください', open: '設定を開く', start: '実行する', view: '実行結果を見る', files: 'ファイルを開く', close: '閉じる', configureState: '設定は環境の検証を意味しません' },
} })
const audio = computed(() => props.nodes.some((node) => node.data.kind === 'whisper') && props.nodes.some((node) => node.data.kind === 'summary'))
const inputNode = computed(() => audio.value ? props.nodes.find((node) => node.data.kind === 'start') ?? props.nodes.find((node) => node.data.kind === 'whisper') : props.nodes.find((node) => node.data.kind === 'prompt') ?? props.nodes.find((node) => node.data.kind === 'image-generation'))
const configNodes = computed(() => props.nodes.filter((node) => audio.value ? ['whisper', 'summary', 'export'].includes(node.data.kind) : ['image-generation', 'upscale'].includes(node.data.kind)))
function fieldFor(node: WorkflowGraphNode) { return node.data.kind === 'whisper' ? 'whisperEnvironment' : node.data.kind === 'summary' ? 'model' : node.data.kind === 'export' ? 'format' : 'connectionId' }
</script>
<template>
  <section data-testid="workflow-starter-guide" class="max-h-80 overflow-y-auto border-b border-app-border bg-primary-soft/30 p-4">
    <div class="flex items-center justify-between gap-2"><h2 class="text-sm font-semibold">{{ t('title') }} · {{ t(audio ? 'audio' : 'image') }}</h2><button type="button" class="text-xs text-primary" @click="emit('close')">{{ t('close') }}</button></div>
    <p class="mt-1 text-xs text-text-muted">{{ t('example') }}</p>
    <ol class="mt-3 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
      <li class="rounded-lg border border-app-border bg-white p-3"><h3 class="text-sm font-semibold">{{ t('input') }}</h3><p class="my-2 text-xs">{{ t(audio ? 'audioInput' : 'imageInput') }}</p><button v-if="inputNode" type="button" class="text-xs text-primary underline" @click="emit('locate', inputNode.id, audio ? 'fileId' : 'prompt')">{{ t('open') }}: {{ inputNode.data.label }}</button></li>
      <li class="rounded-lg border border-app-border bg-white p-3"><h3 class="text-sm font-semibold">{{ t('configure') }}</h3><p class="my-2 text-xs">{{ t(audio ? 'audioConfig' : 'imageConfig') }}</p><button v-for="node in configNodes" :key="node.id" type="button" class="mr-2 text-xs text-primary underline" @click="emit('locate', node.id, fieldFor(node))">{{ node.data.label }}</button><p class="mt-2 text-xs text-text-muted">{{ t('configureState') }}</p></li>
      <li class="rounded-lg border border-app-border bg-white p-3"><h3 class="text-sm font-semibold">{{ t('run') }}</h3><p class="my-2 text-xs">{{ t('runHint') }}</p><button type="button" :disabled="busy" class="rounded border border-primary px-2 py-1 text-xs text-primary disabled:opacity-50" @click="emit('run')">{{ t('start') }}</button></li>
      <li class="rounded-lg border border-app-border bg-white p-3"><h3 class="text-sm font-semibold">{{ t('results') }}</h3><p class="my-2 text-xs">{{ t('resultsHint') }}</p><p class="mb-2 text-xs" role="status">{{ t(!run ? 'pending' : run.backendStatus === 'SUCCESS' ? 'succeeded' : 'unconfirmed') }}</p><button v-if="run" type="button" class="mr-2 text-xs text-primary underline" @click="emit('results')">{{ t('view') }}</button><RouterLink to="/files" class="text-xs text-primary underline">{{ t('files') }}</RouterLink></li>
    </ol>
  </section>
</template>
